//! Design tokens for the engine (T01-010). `tokens.rs` is generated by
//! `client/scripts/gen-tokens.ts` from `design/tokens.toml`; colours are sRGB-encoded bytes equal to
//! the CSS hex, and the engine blends in sRGB-encoded space (T02 §4.2, D-BLEND).

#[rustfmt::skip]
mod tokens;
pub use tokens::*;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Theme {
    Dark,
    Light,
}

/// An sRGB-encoded colour with straight alpha.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rgba8(pub [u8; 4]);

impl Rgba8 {
    /// Each channel / 255; the sRGB values are not linearised (D-BLEND).
    pub fn to_f32(self) -> [f32; 4] {
        self.0.map(|c| f32::from(c) / 255.0)
    }
}

/// The colour roles the engine draws with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ColourRole {
    Surface1,
    Hairline,
    TextMuted,
    Brush,
    Text,
    /// Threshold states (ADR-0022, `StateEncoding`'s colours).
    Watch,
    Degraded,
    Failing,
    /// The selection band (T25-006): `accent` at 16 %.
    Selection,
    /// The selection underlay (T25-006).
    Focus,
}

/// The token of `role` in `theme`.
pub fn colour(theme: Theme, role: ColourRole) -> Rgba8 {
    use tokens::colour::{dark, light};
    match (theme, role) {
        (Theme::Dark, ColourRole::Surface1) => dark::SURFACE_1,
        (Theme::Dark, ColourRole::Hairline) => dark::HAIRLINE,
        (Theme::Dark, ColourRole::TextMuted) => dark::TEXT_MUTED,
        (Theme::Dark, ColourRole::Brush) => dark::BRUSH,
        (Theme::Dark, ColourRole::Text) => dark::TEXT,
        (Theme::Dark, ColourRole::Watch) => dark::WATCH,
        (Theme::Dark, ColourRole::Degraded) => dark::DEGRADED,
        (Theme::Dark, ColourRole::Failing) => dark::FAILING,
        (Theme::Dark, ColourRole::Selection) => dark::SELECTION,
        (Theme::Dark, ColourRole::Focus) => dark::FOCUS,
        (Theme::Light, ColourRole::Surface1) => light::SURFACE_1,
        (Theme::Light, ColourRole::Hairline) => light::HAIRLINE,
        (Theme::Light, ColourRole::TextMuted) => light::TEXT_MUTED,
        (Theme::Light, ColourRole::Brush) => light::BRUSH,
        (Theme::Light, ColourRole::Text) => light::TEXT,
        (Theme::Light, ColourRole::Watch) => light::WATCH,
        (Theme::Light, ColourRole::Degraded) => light::DEGRADED,
        (Theme::Light, ColourRole::Failing) => light::FAILING,
        (Theme::Light, ColourRole::Selection) => light::SELECTION,
        (Theme::Light, ColourRole::Focus) => light::FOCUS,
    }
}

/// The eight series colours of `theme` (slot = `series_colour_index`).
pub fn series_palette(theme: Theme) -> [Rgba8; 8] {
    SERIES_PALETTE[match theme {
        Theme::Dark => 0,
        Theme::Light => 1,
    }]
}
